//! The Tutor's English word list, `tutor_words_en.txt`: real words, most
//! frequent first, and the letter order that forms the most words early.
//! It is generated by `tools/gen_tutor_words.zig` and parsed once, on first
//! use, into the letters each word needs.
const std = @import("std");

pub const max_words: usize = 32_768;
pub const english_source = @embedFile("tutor_words_en.txt");

pub const Word = struct {
    start: u32,
    len: u8,
    /// Bit `c - 'a'` for every letter `c` of the word.
    mask: u32,
};

pub const List = struct {
    text: []const u8 = "",
    items: [max_words]Word = undefined,
    len: usize = 0,
    order: [26]u8 = @splat(0),
    order_len: usize = 0,

    pub fn word(self: *const List, index: usize) []const u8 {
        const w = self.items[index];
        return self.text[w.start..][0..w.len];
    }

    /// Letters in the order that forms the most frequent words early.
    pub fn letterOrder(self: *const List) []const u8 {
        return self.order[0..self.order_len];
    }
};

const order_prefix = "# letter order: ";

/// Reads a word list: `#` lines are comments, except the letter order; every
/// other line is one lower-case word. Lines that are not are skipped.
pub fn parse(text: []const u8, out: *List) void {
    out.text = text;
    out.len = 0;
    out.order_len = 0;
    var start: usize = 0;
    while (start < text.len) {
        const end = std.mem.indexOfScalarPos(u8, text, start, '\n') orelse text.len;
        const line = std.mem.trimEnd(u8, text[start..end], "\r");
        defer start = end + 1;
        if (std.mem.startsWith(u8, line, order_prefix)) {
            const letters = line[order_prefix.len..];
            for (letters) |c| {
                if (c < 'a' or c > 'z' or out.order_len == out.order.len) continue;
                if (std.mem.indexOfScalar(u8, out.order[0..out.order_len], c) != null) continue;
                out.order[out.order_len] = c;
                out.order_len += 1;
            }
            continue;
        }
        if (line.len == 0 or line[0] == '#' or line.len > std.math.maxInt(u8)) continue;
        const mask = maskOf(line) orelse continue;
        if (out.len == max_words) break;
        out.items[out.len] = .{ .start = @intCast(start), .len = @intCast(line.len), .mask = mask };
        out.len += 1;
    }
}

/// The letter mask of a lower-case a-z word, null for anything else.
pub fn maskOf(word: []const u8) ?u32 {
    var mask: u32 = 0;
    for (word) |c| {
        if (c < 'a' or c > 'z') return null;
        mask |= @as(u32, 1) << @intCast(c - 'a');
    }
    return mask;
}

var english_list: List = .{};
var english_ready = false;

/// The bundled English list, parsed on first use.
pub fn english() *const List {
    if (!english_ready) {
        parse(english_source, &english_list);
        english_ready = true;
    }
    return &english_list;
}

test "the bundled list holds tens of thousands of clean words and a full letter order" {
    const t = std.testing;
    const list = english();
    try t.expect(list.len >= 20_000);
    try t.expectEqual(@as(usize, 26), list.letterOrder().len);
    var seen: std.StringHashMapUnmanaged(void) = .empty;
    defer seen.deinit(t.allocator);
    for (0..list.len) |i| {
        const w = list.word(i);
        try t.expect(w.len >= 3 and w.len <= 14);
        try t.expectEqual(maskOf(w).?, list.items[i].mask);
        try t.expect(!(try seen.getOrPut(t.allocator, w)).found_existing);
    }
    // Most frequent first.
    try t.expectEqualStrings("you", list.word(0));
}

test "a word list ignores comments, blank lines and words that are not lower-case a-z" {
    const t = std.testing;
    var list: List = .{};
    parse("# heading\n# letter order: eat\n\nate\r\nTea\nno-go\neat\n", &list);
    try t.expectEqualStrings("eat", list.letterOrder());
    try t.expectEqual(@as(usize, 2), list.len);
    try t.expectEqualStrings("ate", list.word(0));
    try t.expectEqualStrings("eat", list.word(1));
}
